<?php
declare(strict_types=1);
require dirname(__DIR__).'/services/ChatReadService.php';
$db=new PDO('sqlite::memory:');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);
$db->exec('CREATE TABLE chat_read_cursors(user_id INTEGER,scope TEXT,conversation_id INTEGER,last_message_id INTEGER,PRIMARY KEY(user_id,scope,conversation_id));CREATE TABLE messages(id INTEGER PRIMARY KEY,channel_id INTEGER,sender_id INTEGER,created_at TEXT,is_deleted INTEGER DEFAULT 0);CREATE TABLE dm_messages(id INTEGER PRIMARY KEY,conversation_id INTEGER,group_id INTEGER,sender_id INTEGER,created_at TEXT,is_deleted INTEGER DEFAULT 0);CREATE TABLE message_reads(user_id INTEGER,channel_id INTEGER,last_read_at TEXT);CREATE TABLE dm_reads(user_id INTEGER,conversation_id INTEGER,last_read_at TEXT)');
$db->exec("INSERT INTO messages(id,channel_id,sender_id,created_at) VALUES(1,7,2,'2026-10-19 15:59:59'),(2,7,1,'2026-10-19 16:00:00'),(3,7,2,'2026-10-19 16:00:00'),(4,7,2,'2026-10-19 16:00:00');INSERT INTO message_reads VALUES(1,7,'2026-10-19 15:59:59');INSERT INTO dm_messages(id,conversation_id,group_id,sender_id,created_at) VALUES(1,7,NULL,2,'2026-10-19 16:00:00'),(2,NULL,7,2,'2026-10-19 16:00:00'),(3,NULL,8,2,'2026-10-19 16:00:00')");
function check(bool $yes,string $label):void{if(!$yes)throw new RuntimeException($label);}
$r=new ChatReadService($db);check($r->snapshot('channel',7,1)===['last_read_id'=>1,'first_unread_id'=>3],'Legacy reads retained, own messages excluded');$r->mark('channel',7,1,[['id'=>3]]);check($r->snapshot('channel',7,1)['first_unread_id']===4,'Later message in same second stays unread');$r->mark('channel',7,1,[['id'=>2]]);check($r->snapshot('channel',7,1)['last_read_id']===3,'Delayed old page cannot move read cursor backwards');check($r->snapshot('channel',7,3)['first_unread_id']===1,'Read state isolated by user');check($r->snapshot('dm',7,1)['first_unread_id']===1,'Direct messages have independent scope');check($r->snapshot('group',7,1)['first_unread_id']===2,'Groups have independent scope');$r->mark('group',7,1,[],999);check($r->snapshot('group',7,1)['last_read_id']===2,'Catch-up ack is bounded to messages in this group');check($r->snapshot('group',8,1)['first_unread_id']===3,'Another group stays unread');$r->mark('channel',7,1,[],4);check($r->snapshot('channel',7,1)['first_unread_id']===null,'Visible live messages acknowledged without fetching duplicate history');echo "PASS: legacy read fallback, unread snapshots, same-second delivery, monotonic and per-user/scope read state\n";
